{"cards": [{"node_code": "N_1f654a51a8ccde1b", "definition": "指免疫系统针对特定器官或组织中的特异性抗原产生免疫应答，导致该器官或组织发生特异性损伤和功能障碍的自身免疫性疾病。", "boundary": "本节点收录病变局限于单一器官或组织，且存在器官特异性自身抗体或T细胞的疾病。包括甲状腺（如Graves病、桥本甲状腺炎）、胰腺（如1型糖尿病）、神经系统（如多发性硬化）等。与系统性自身免疫病的区别在于，本节点疾病通常不伴有全身多系统受累或多种非器官特异性自身抗体。", "includes": ["甲状腺自身免疫病（如Graves病、桥本甲状腺炎）", "胰腺自身免疫病（如1型糖尿病）", "神经系统自身免疫病（如多发性硬化、重症肌无力）"], "excludes": ["累及多个器官系统且伴有多种非器官特异性自身抗体的疾病（归入系统性自身免疫病）"], "sibling_distinctions": [{"other_code": "N_e2d0009246b63e4a", "rule": "器官特异性自身免疫病针对特定器官抗原，病变局限；系统性自身免疫病针对核抗原等广泛抗原，累及多系统。"}], "cross_boundary_rule": ""}, {"node_code": "N_e2d0009246b63e4a", "definition": "指免疫系统针对细胞核、细胞质等广泛分布的自身抗原产生免疫应答，导致全身多个器官系统同时或相继发生损伤的自身免疫性疾病。", "boundary": "本节点收录病变累及全身多个系统，常伴有多种非器官特异性自身抗体（如抗核抗体）的疾病。包括系统性红斑狼疮、类风湿关节炎、干燥综合征、系统性硬化症等。与器官特异性自身免疫病的区别在于，本节点疾病具有全身性、多系统受累及免疫复合物沉积等特征。", "includes": ["系统性红斑狼疮（SLE）", "类风湿关节炎（RA）", "干燥综合征、系统性硬化症、混合性结缔组织病"], "excludes": ["仅累及单一器官且存在器官特异性自身抗体的疾病（归入器官特异性自身免疫病）"], "sibling_distinctions": [{"other_code": "N_1f654a51a8ccde1b", "rule": "系统性自身免疫病累及多系统，针对广泛抗原；器官特异性自身免疫病病变局限，针对特定器官抗原。"}], "cross_boundary_rule": ""}]}
